// The list of the push kinds that scripts/gen-features.ts writes (#426).
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import {
  generatePushTopics,
  PUSH_TOPICS_DIR,
  PUSH_TOPICS_FILE,
  renderPushTopics,
  scanPushTopics,
} from '../../scripts/gen-features.ts';

describe('the list of the push kinds (#426)', () => {
  let dir: string;
  const HEADER =
    '// Generated by scripts/gen-features.ts; not checked in, do not edit.\n';
  const write = (file: string, source = 'export const pushTopics = [];\n') => {
    mkdirSync(path.dirname(path.join(dir, file)), { recursive: true });
    writeFileSync(path.join(dir, file), source);
  };

  beforeEach(() => {
    dir = path.join(mkdtempSync(path.join(tmpdir(), 'nova-')), 'push-topics');
  });
  afterEach(() => rmSync(path.dirname(dir), { recursive: true, force: true }));

  it('is written before the tests run', () => {
    expect(
      readFileSync(path.join(PUSH_TOPICS_DIR, PUSH_TOPICS_FILE), 'utf8'),
    ).toBe(renderPushTopics(scanPushTopics(PUSH_TOPICS_DIR)));
  });

  it('is empty but valid for an empty or missing folder', () => {
    expect(scanPushTopics(dir)).toEqual([]);
    expect(generatePushTopics(dir)).toBe(true);
    expect(readFileSync(path.join(dir, PUSH_TOPICS_FILE), 'utf8')).toBe(
      `${HEADER}\nexport const PUSH_TOPIC_LISTS = [] as const;\n`,
    );
  });

  it('imports every file that exports pushTopics, sorted, and writes only a change', () => {
    write('queues.ts');
    write('fleet.ts');
    write('other.ts', 'export const other = 1;\n');
    write('fleet.test.ts');
    write(PUSH_TOPICS_FILE);
    write('x.ts', 'export const mypushTopics = [];\n');
    expect(scanPushTopics(dir)).toEqual(['fleet.ts', 'queues.ts']);
    expect(generatePushTopics(dir)).toBe(true);
    expect(generatePushTopics(dir)).toBe(false);
    expect(readFileSync(path.join(dir, PUSH_TOPICS_FILE), 'utf8')).toBe(
      [
        HEADER,
        "import { pushTopics as feature_fleet } from './fleet.ts';",
        "import { pushTopics as feature_queues } from './queues.ts';",
        '',
        'export const PUSH_TOPIC_LISTS = [',
        "  ['fleet', feature_fleet],",
        "  ['queues', feature_queues],",
        '] as const;',
        '',
      ].join('\n'),
    );
  });
});
